function init(){randomizeWorld();t=0;animals=Array.from({length:10},(_,i)=>{const a=species[i%10],copy=Math.floor(i/10),x=copy===0?390+(i%4)*190:1200+(i*739)%3500,y=copy===0?140+Math.floor(i/4)*175:650+(i*397)%1900;return{name:a[0],type:a[1],speciesIndex:i%10,x,y,originX:x,originY:y,status:'wild',phase:i*1.7}});for(let j=0;j<5;j++){const x=450+(j*367)%4300,y=700+(j*251)%1900;animals.push({name:'Bunnies',type:'bunny',speciesIndex:8,x,y,originX:x,originY:y,status:'wild',phase:j*1.9})}animals.filter(a=>a.type==='bunny').forEach((a,j)=>{a.bunnyColor=j===4?'pink':j%3===0?'blue':'white';a.isPair=Math.random()<.1;a.value=(a.bunnyColor==='pink'?100:a.bunnyColor==='blue'?50:10)+(a.isPair?50:0);a.name=(a.bunnyColor==='pink'?'Rare pink':a.bunnyColor==='blue'?'Blue':'White')+(a.isPair?' bunny pair':' bunny')});animals.filter(a=>a.type!=='babyotter').forEach((a,i)=>{a.x=520+(i%7)*650+Math.sin(i*2.3)*70;a.y=300+Math.floor(i/7)*440+Math.cos(i*1.7)*65;a.originX=a.x;a.originY=a.y});animals.filter(a=>a.type==='bunny').forEach((bunny,j)=>{if(j<5){const patch=grassPatches[j%grassPatches.length];bunny.x=j%3===1?bunnyMeadow.x+200+j%4*300:patch.x+30+(j*13)%100;bunny.y=j%3===1?bunnyMeadow.z+140+Math.floor(j/4)*330:patch.z+35+(j*17)%80;bunny.originX=bunny.x;bunny.originY=bunny.y;bunny.bunnyMeadow=true}});animals.filter(a=>a.type==='parrot').forEach((rio,i)=>{const cherryTrees=trees.filter(tree=>!tree.evergreen);rio.perch=cherryTrees[Math.floor(Math.random()*cherryTrees.length)];rio.perchBranch=treeBranches(rio.perch)[Math.floor(Math.random()*5)];rio.flightOffset=i*7;rio.height=0});const mamas=animals.filter(a=>a.type==='otter');animals.filter(a=>a.type==='babyotter').forEach((baby,i)=>{baby.mama=mamas[i];baby.mama.baby=baby;baby.x=baby.mama.x;baby.y=baby.mama.y;baby.carried=true;baby.mama.resting=true;baby.hopRemaining=0});player={x:180,y:320};yaw=0;cameraYaw=0;lookPitch=0;steps=0;points=0;jumpHeight=0;jumpVelocity=0;playerCatchTimer=0;catchBursts=[];stamina=100;sprinting=false;sprintExhausted=false;sprintRecoveryTimer=0;sprintLock=false;staminaDelay=0;const sprintButton=document.querySelector('[data-act=\"sprint\"]');if(sprintButton){sprintButton.classList.remove('is-locked');sprintButton.textContent='Sprint OFF'}drinks=[];drinkSpawnTimer=5;staminaPickups=[];staminaPickupSpawnTimer=9;playerDrinkTimer=0;speedBoostTimer=0;roundTime=183;startCountdown=0;bunnyBonusCount=0;refreshTimer();refreshStamina();for(const a of animals)if(!a.carried){moveSolid(a,a.x,a.y,animalRadius(a));a.originX=a.x;a.originY=a.y}assignHidingPlaces();pointBonuses=[];bonusSpawnTimer=4;foodBags=[];droppedPellets=[];pelletCount=0;foodSpawnTimer=7;refreshFood();eiza={x:player.x+650,y:player.y+200,heading:Math.PI,cooldown:0};refresh()}
let lastStaminaUpdate=-Infinity;function refreshStamina(){if(t-lastStaminaUpdate>=0&&t-lastStaminaUpdate<.1)return;lastStaminaUpdate=t;document.getElementById('boost-label').textContent=speedBoostTimer>0?'⚡ Speed boost · '+speedBoostTimer.toFixed(1)+'s':'';const bar=document.getElementById('stamina-fill');bar.style.width=stamina+'%';bar.style.background=sprintExhausted?'#c88769':stamina<30?'#d2ad58':'#729957';document.getElementById('stamina-meter').setAttribute('aria-valuenow',Math.round(stamina));document.getElementById('stamina-label').textContent=sprintExhausted?'Stamina · recovering':'Stamina'}
let lastTimerText='';function refreshTimer(){const seconds=Math.ceil(roundTime),text=Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0');if(text!==lastTimerText){document.getElementById('round-timer').textContent=text;lastTimerText=text}}
function refresh(){document.getElementById('points').textContent='Points: '+points;const saved=animals.filter(a=>a.type!=='bunny'&&a.status==='home').length,following=animals.filter(a=>a.status==='following').length;document.getElementById('following').textContent='Following: '+following;const nextMultiplier=followerMultiplier();document.getElementById('multiplier').textContent='×'+(Number.isInteger(nextMultiplier)?nextMultiplier:nextMultiplier.toFixed(1));document.getElementById('saved').textContent='Home: '+saved+' / 9';document.getElementById('total').textContent=saved+' / 9 friends';document.getElementById('who').textContent=heroes[chosen].name+(heroes[chosen].space?' · E: Dive':heroes[chosen].viking?' · Wide catch':' · Fast paws');species.forEach((s,i)=>{const count=animals.filter(a=>a.speciesIndex===i&&a.status==='home').length,card=document.getElementById('card'+i);const total=animals.filter(a=>a.speciesIndex===i).length;card?.classList.toggle('found',count===total);const label=card?.querySelector('div');if(label)label.textContent=i===8?'Bunnies · '+bunnyBonusCount+' bonus':s[0]+' · '+count+'/'+total})}
const difficultyModes={easy:{name:'Easy',speed:.6,range:1.5,flee:.65,perch:6,ground:12,obstacles:0},normal:{name:'Normal',speed:.82,range:1.2,flee:.82,perch:9,ground:9,obstacles:8},hard:{name:'Hard',speed:1,range:1,flee:1,perch:12,ground:7,obstacles:16},extra:{name:'Extra Hard',speed:1.12,range:.8,flee:1.15,perch:16,ground:5,obstacles:24}};let difficulty='hard';try{const saved=localStorage.getItem('kutopia-difficulty');if(difficultyModes[saved])difficulty=saved}catch{}function modeSettings(){return difficultyModes[difficulty]}function selectDifficulty(value){if((state!=='ready'&&state!=='won')||!difficultyModes[value])return;difficulty=value;try{localStorage.setItem('kutopia-difficulty',value)}catch{}for(const button of document.querySelectorAll('[data-difficulty]'))button.setAttribute('aria-pressed',String(button.dataset.difficulty===difficulty))}function setupDifficulty(){const group=document.createElement('div');group.id='difficulty-options';group.className='difficulty-options';group.setAttribute('role','group');group.setAttribute('aria-label','Catching difficulty');group.innerHTML='<span>Catch difficulty</span>'+Object.entries(difficultyModes).map(([value,mode])=>'<button type="button" data-difficulty="'+value+'" aria-pressed="'+(value===difficulty)+'">'+mode.name+'</button>').join('');document.getElementById('characters').after(group);for(const button of group.querySelectorAll('button'))button.addEventListener('click',()=>selectDifficulty(button.dataset.difficulty));}setupDifficulty();
function photoWrapReset(){const photoWrap=document.getElementById('family-photo-wrap');photoWrap.style.opacity='1';photoWrap.style.transition=''}function start(){howToButton.hidden=true;roundEndTimer=0;musicGoEnabled=false;roundTransitionShade.classList.remove('active');document.getElementById('round-timer').classList.remove('round-time-up');photoWrapReset();diveTimer=0;diveCooldown=0;diveRecoveryTimer=0;diveImpactTimer=0;diveSlideTimer=0;photoLayoutSeed=Math.floor(Math.random()*2147483647);familyMembers=[];document.getElementById('family-photo-wrap').classList.add('hidden');pendingScore=null;document.getElementById('score-entry').classList.add('hidden');document.getElementById('score-saved').textContent='';init();startCountdown=3;state='playing';overlay.classList.add('hidden');keys.clear();syncMusic();hint.textContent=modeSettings().name+' mode: find the animals and bring them to The Nest!'}
function pause(){if(state==='playing'){state='paused';keys.clear();showPanel('A little rest.','Your friends are waiting right here.','Keep exploring →',false)}else if(state==='paused'){state='playing';overlay.classList.add('hidden');startMusic()}}
function showPanel(title,message,label,characters){document.getElementById('pause-actions')?.classList.toggle('hidden',state!=='paused');document.getElementById('difficulty-options')?.classList.toggle('hidden',state==='paused');document.getElementById('title').textContent=title;document.getElementById('message').textContent=message;document.getElementById('start').textContent=label;document.getElementById('characters').classList.toggle('hidden',!characters);document.getElementById('leaderboard').classList.toggle('hidden',!characters);document.getElementById('family-photo-wrap').classList.toggle('hidden',state!=='won');document.getElementById('round-end-actions')?.classList.toggle('hidden',state!=='won');renderLeaderboard();overlay.classList.remove('hidden');if(state==='won')document.querySelector('.panel').scrollTop=0}
let diveTimer=0,diveCooldown=0,diveHeading=0,diveRecoveryTimer=0,diveImpactTimer=0,diveSlideTimer=0;function startDive(){if(state!=='playing'||diveCooldown>0||diveRecoveryTimer>0)return;diveTimer=.42;diveCooldown=1.1;diveRecoveryTimer=0;diveHeading=yaw;hint.textContent='Dive into an animal to catch it!'}function catchRange(a){return (a.type==='runner'?33:a.type==='parrot'?48:a.type==='bunny'&&a.bunnyColor==='white'?60:a.type==='bunny'&&a.bunnyColor==='blue'?52:46)*modeSettings().range*(heroes[chosen].viking?1.22:heroes[chosen].dog?1.5:1)}
function followerMultiplier(){const weight=animals.filter(a=>a.status==='following').reduce((sum,a)=>sum+(a.type==='bunny'?0.5:1),0);return Math.min(10,1+weight)}const celebrationClips={kasanova:new Audio('data:audio/mpeg;base64,'),cedonas:new Audio('data:audio/mpeg;base64,'),bronxie:new Audio('data:audio/mpeg;base64,')};for(const clip of Object.values(celebrationClips)){clip.preload='auto';clip.volume=1}function playCelebrationClip(name){const clip=celebrationClips[name];if(!clip)return;try{clip.pause();clip.currentTime=0;const playback=clip.play();if(playback?.catch)playback.catch(()=>{})}catch{}}function playBronxieBark(){playCelebrationClip('bronxie')}function playHeroCelebrationVoice(){if(chosen===0)playCelebrationClip('kasanova');else if(chosen===1)playCelebrationClip('cedonas')}function befriend(touched=null){if(state!=='playing')return;if(heroes[chosen].space&&!touched){startDive();return;}if(speedBoostTimer<=0&&animals.some(a=>a.type==='runner'&&a.status==='wild'&&!a.hidden&&Math.hypot(a.x-player.x,a.y-player.y)<catchRange(a))){hint.textContent='Meep is too quick! Grab a pink drink speed boost to catch him.';return}const near=animals.filter(a=>a.status==='wild'&&!a.hidden&&(a.type!=='runner'||speedBoostTimer>0)&&Math.abs((a.height||0)-jumpHeight)<(a.type==='parrot'?115:25)&&(touched?a===touched&&Math.hypot(a.x-player.x,a.y-player.y)<animalRadius(a)+18:Math.hypot(a.x-player.x,a.y-player.y)<catchRange(a))).sort((a,b)=>Math.hypot(a.x-player.x,a.y-player.y)-Math.hypot(b.x-player.x,b.y-player.y))[0];if(near){const friend=near.mama||near,catchMultiplier=followerMultiplier();friend.status='following';friend.resting=false;friend.height=castleCameraBase();let catchReward=0;for(const caught of [friend,...(friend.baby?[friend.baby]:[])]){caught.catchTimer=CATCH_CELEBRATION_DURATION;const reward={dog:150,parrot:500,runner:1000,spider:200,skunk:75,otter:150,babyotter:75,goat:60,tapir:62}[caught.type]||caught.value||0;if(reward&&!caught.catchRewardClaimed){points+=reward*catchMultiplier;catchReward+=reward*catchMultiplier;caught.catchPoints=reward*catchMultiplier;caught.catchRewardClaimed=true;}}playerCatchTimer=CATCH_CELEBRATION_DURATION;playHeroCelebrationVoice();if(heroes[chosen].dog)playBronxieBark();catchBursts.push({x:friend.x,y:friend.y,time:1.2,text:catchReward?'+'+catchReward+' points!'+(catchMultiplier>1?' ×'+catchMultiplier:''):'New friend!'});if(friend.baby){friend.baby.status='following';hint.textContent='Mama Otter and her baby are coming together! +225 points! Jump onto The Nest bed to tuck them in.'}else hint.textContent=friend.name+' is your new friend! '+(catchReward?'+'+catchReward+' points!'+(catchMultiplier>1?' ×'+catchMultiplier:'')+' ':'')+'Jump onto The Nest bed to tuck them in.';refresh()}else hint.textContent=animals.some(a=>a.type==='parrot'&&a.status==='wild'&&a.height>=25&&Math.hypot(a.x-player.x,a.y-player.y)<180)?'Rio is high in the blossoms. Jump and catch when Rio is within reach.':'Walk a little closer to a wild animal, then press E.'}
function drawCharacterPortrait(canvas,index){const ctx=canvas.getContext('2d');ctx.clearRect(0,0,canvas.width,canvas.height);if(!familyCutouts.complete||!familyCutouts.naturalWidth)return;const cw=familyCutouts.naturalWidth/4,ch=familyCutouts.naturalHeight/4,size=Math.min(canvas.width,canvas.height)-6;ctx.drawImage(familyCutouts,index*cw,0,cw,ch,(canvas.width-size)/2,(canvas.height-size)/2,size,size)}function paintMenuPortraits(){for(const [index,card] of Array.from(document.getElementById('characters').children).entries()){const portrait=card.querySelector('canvas');if(portrait)drawCharacterPortrait(portrait,index)}}const characterBox=document.getElementById('characters');heroes.forEach((h,i)=>{const b=document.createElement('button');b.className='character';b.setAttribute('aria-pressed',String(i===chosen));b.innerHTML='<strong>'+h.name+'</strong><small>'+h.desc+'</small>';const portrait=document.createElement('canvas');portrait.width=120;portrait.height=110;portrait.style.background='transparent';portrait.setAttribute('aria-label',h.desc);drawCharacterPortrait(portrait,i);b.insertBefore(portrait,b.firstChild);b.onclick=()=>{chosen=i;[...characterBox.children].forEach((el,j)=>el.setAttribute('aria-pressed',String(j===i)));refresh()};characterBox.appendChild(b)});
species.forEach(([name,type],i)=>{const d=document.createElement('div');d.className='card';d.id='card'+i;const cv=document.createElement('canvas');cv.width=100;cv.height=100;cv.setAttribute('aria-label',name);animalArt(cv.getContext('2d'),type,50,type==='runner'?69:54,type==='runner'?.95:1.2);d.appendChild(cv);const label=document.createElement('div');label.textContent=name;d.appendChild(label);document.getElementById('collection').appendChild(d)});
