document.getElementById('score-entry').addEventListener('submit',e=>{e.preventDefault();saveHighScore(document.getElementById('leaderboard-name').value)});addEventListener('keydown',e=>{if(e.target?.tagName==='INPUT')return;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();keys.add(e.code);if(!e.repeat){if(e.code==='Space'&&state==='playing'&&jumpVelocity===0&&jumpHeight<=platformHeight(player.x,player.y)+.01){jumpVelocity=290}if(e.code==='KeyQ')dropPellet();if(e.code==='KeyE')befriend();if(e.code==='KeyP')pause();if(e.code==='Enter'&&(state==='ready'||state==='won'))start()}});addEventListener('keyup',e=>keys.delete(e.code));addEventListener('blur',()=>{keys.clear();if(state==='playing')pause()});
function updateRios(dt){for(const rio of animals.filter(a=>a.type==='parrot')){rio.hidden=false;if(rio.status!=='wild'){rio.height=0;rio.perched=false;rio.flying=false;continue}const tree=rio.perch,branch=rio.perchBranch,landing={x:tree.x+branch.dx*.82,y:tree.z+branch.dz*.82,height:branch.baseHeight+(branch.tipHeight-branch.baseHeight)*.82};if(!rio.flightState){rio.flightState='perched';rio.flightRemaining=modeSettings().perch}rio.flightRemaining-=dt;if(rio.flightRemaining<=0){const next={perched:'descending',descending:'ground',ground:'ascending',ascending:'perched'}[rio.flightState];rio.flightState=next;rio.flightRemaining={perched:modeSettings().perch,descending:4,ground:modeSettings().ground,ascending:3}[next];if(next==='descending'){rio.flightTarget={x:Math.max(50,Math.min(WORLD_W-50,tree.x+110)),y:Math.max(90,Math.min(WORLD_H-50,tree.z+50)),height:0}}if(next==='ascending')rio.flightTarget=landing}rio.perched=rio.flightState==='perched';rio.flying=rio.flightState==='ascending'||rio.flightState==='descending';if(rio.perched){rio.x=landing.x;rio.y=landing.y;rio.height=landing.height}else if(rio.flying){const target=rio.flightTarget||landing,mix=Math.min(1,dt/Math.max(dt,rio.flightRemaining+dt));rio.x+=(target.x-rio.x)*mix;rio.y+=(target.y-rio.y)*mix;rio.height+=(target.height-rio.height)*mix}else{const dx=rio.x-player.x,dy=rio.y-player.y,close=Math.hypot(dx,dy)<210*modeSettings().flee,angle=close?Math.atan2(dy,dx):t*.25+rio.phase;if(close)rio.radarRevealed=true;rio.flying=close;rio.height=close?8+Math.abs(Math.sin(t*12))*8:0;rio.x=Math.max(40,Math.min(WORLD_W-40,rio.x+Math.cos(angle)*(close?255:45)*modeSettings().speed*waterSpeedFactor(rio.x,rio.y,rio.height||0)*dt));rio.y=Math.max(85,Math.min(WORLD_H-40,rio.y+Math.sin(angle)*(close?255:45)*modeSettings().speed*dt))}}}

function syncBabies(dt){for(const baby of animals.filter(a=>a.mama)){const mama=baby.mama;baby.status=mama.status;baby.fleeing=mama.fleeing;if(mama.hidden){baby.hidden=true;baby.x=mama.x;baby.y=mama.y;continue}if(mama.status==='home'){mama.resting=true;baby.carried=false;baby.sleeping=true;baby.height=53;continue}if(mama.resting){baby.carried=true;baby.hopRemaining=0;baby.height=0;baby.x=mama.x;baby.y=mama.y;baby.heading=mama.heading;continue}if(baby.carried){baby.carried=false;baby.hopRemaining=.65;baby.x=mama.x+Math.cos(mama.heading||0)*18;baby.y=mama.y+Math.sin(mama.heading||0)*18}if(baby.hopRemaining>0){baby.hopRemaining=Math.max(0,baby.hopRemaining-dt);const u=1-baby.hopRemaining/.65;baby.height=(1-u)*18+Math.sin(u*Math.PI)*22}else baby.height=0;const dx=mama.x-baby.x,dy=mama.y-baby.y,dist=Math.hypot(dx,dy);if(dist>38){const move=Math.min(dist-38,Math.max(310,dist*8)*waterSpeedFactor(baby.x,baby.y,baby.height||0)*dt);baby.x+=dx/dist*move;baby.y+=dy/dist*move;if(dist-move>65){baby.x=mama.x-dx/dist*65;baby.y=mama.y-dy/dist*65}}}}
function animalRadius(a){return a.type==='bunny'?6:a.type==='babyotter'?6:a.type==='skunk'?7:a.type==='spider'?20:11}
function closestSolid(shape,x,z,radius){if(shape.type==='circle'){const dx=x-shape.x,dz=z-shape.z,dist=Math.hypot(dx,dz),limit=radius+shape.radius;if(dist>=limit)return null;return{x:shape.x+(dx/(dist||1)||1)*limit,z:shape.z+dz/(dist||1)*limit}}if(shape.type==='capsule'){const u=Math.max(-shape.half,Math.min(shape.half,x-shape.x)),cx=shape.x+u,dx=x-cx,dz=z-shape.z,dist=Math.hypot(dx,dz),limit=radius+shape.radius;if(dist>=limit)return null;return{x:cx+dx/(dist||1)*limit,z:shape.z+(dz/(dist||1)||1)*limit}}const minX=shape.x-shape.halfX-radius,maxX=shape.x+shape.halfX+radius,minZ=shape.z-shape.halfZ-radius,maxZ=shape.z+shape.halfZ+radius;if(x<=minX||x>=maxX||z<=minZ||z>=maxZ)return null;const options=[{d:x-minX,x:minX,z},{d:maxX-x,x:maxX,z},{d:z-minZ,x,z:minZ},{d:maxZ-z,x,z:maxZ}];options.sort((a,b)=>a.d-b.d);return options[0]}
function moveSolid(entity,targetX,targetY,radius,height=0,from=null){let x=from?from.x:entity.x,z=from?from.y:entity.y;const dx=targetX-x,dz=targetY-z,steps=Math.max(1,Math.ceil(Math.hypot(dx,dz)/5));for(let step=0;step<steps;step++){x+=dx/steps;z+=dz/steps;for(let pass=0;pass<4;pass++){let hit=false;for(const shape of solidShapes){if(height>=shape.height||height<(shape.baseHeight||0)-10)continue;const pushed=closestSolid(shape,x,z,radius);if(pushed){x=pushed.x;z=pushed.z;hit=true}}if(!hit)break}}entity.x=x;entity.y=z}
function platformHeight(x,z){let height=castleSupport(x,z,jumpHeight);for(const shape of solidShapes)if(shape.platform&&!shape.castleStep&&closestSolid(shape,x,z,0))height=Math.max(height,shape.height);return height}
function updateDrinks(dt){playerDrinkTimer=Math.max(0,playerDrinkTimer-dt);drinkSpawnTimer-=dt;if(drinkSpawnTimer<=0){drinkSpawnTimer=7+Math.random()*5;if(drinks.length<2){for(let attempt=0;attempt<12;attempt++){const angle=yaw+(Math.random()-.5)*Math.PI*1.6,distance=100+Math.random()*240,x=Math.max(45,Math.min(WORLD_W-45,player.x+Math.cos(angle)*distance)),y=Math.max(85,Math.min(WORLD_H-45,player.y+Math.sin(angle)*distance));if(!solidShapes.some(shape=>closestSolid(shape,x,y,15))&&!drinks.some(d=>Math.hypot(d.x-x,d.y-y)<50)){drinks.push({x,y,life:3,color:'#efafca'});break}}}}for(const drink of drinks){drink.life-=dt;if(Math.hypot(drink.x-player.x,drink.y-player.y)<28&&jumpHeight<18){drink.life=0;speedBoostTimer=5;playerDrinkTimer=1.2;catchBursts.push({x:player.x,y:player.y,time:1.2,text:'Speed boost!'});hint.textContent='Zoom! Five seconds of extra speed.';refreshStamina()}}drinks=drinks.filter(drink=>drink.life>0)}
function updateStaminaPickups(dt){staminaPickupSpawnTimer-=dt;if(staminaPickupSpawnTimer<=0){staminaPickupSpawnTimer=13+Math.random()*9;if(staminaPickups.length<2){for(let attempt=0;attempt<16;attempt++){const angle=Math.random()*Math.PI*2,distance=130+Math.random()*320,x=Math.max(45,Math.min(WORLD_W-45,player.x+Math.cos(angle)*distance)),y=Math.max(85,Math.min(WORLD_H-45,player.y+Math.sin(angle)*distance));if(!inWater(x,y)&&!solidShapes.some(shape=>closestSolid(shape,x,y,16))&&!staminaPickups.some(p=>Math.hypot(p.x-x,p.y-y)<70)){staminaPickups.push({x,y,life:12,recovery:20+Math.floor(Math.random()*56),phase:Math.random()*6.28});break}}}}for(const pickup of staminaPickups){pickup.life-=dt;pickup.phase+=dt*4;if(Math.hypot(pickup.x-player.x,pickup.y-player.y)<30&&jumpHeight<18){pickup.life=0;stamina=Math.min(100,stamina+pickup.recovery);catchBursts.push({x:player.x,y:player.y,time:1.5,text:'+'+pickup.recovery+'% stamina!'});hint.textContent='Stamina restored by '+pickup.recovery+'%!';refreshStamina()}}staminaPickups=staminaPickups.filter(p=>p.life>0)}
function staminaPickupArt(pickup){const q=project(pickup.x,pickup.y);if(!q||q.depth>1500)return;const s=q.scale,bob=Math.sin(pickup.phase)*3*s;c.save();c.translate(q.x,q.y+bob);c.shadowColor='#a9ffd9';c.shadowBlur=18*s;ellipse(c,0,-16*s,12*s,13*s,'#45d99dcc');c.shadowBlur=0;ellipse(c,0,-16*s,8*s,9*s,'#d7ffeb');c.fillStyle='#258c64';c.font='900 '+Math.max(10,12*s)+'px system-ui';c.textAlign='center';c.textBaseline='middle';c.fillText('+',0,-16*s);c.fillStyle='#fff';c.font='900 '+Math.max(10,11*s)+'px system-ui';c.shadowColor='#18885c';c.shadowBlur=5*s;c.fillText(pickup.recovery+'%',0,-37*s);c.restore()}
function drinkArt(drink){const q=project(drink.x,drink.y);if(!q||q.depth>1500)return;const s=q.scale;c.save();c.translate(q.x,q.y);ellipse(c,0,0,14*s,5*s,'#fff5bc88');c.fillStyle=drink.color;c.beginPath();c.roundRect(-9*s,-22*s,18*s,22*s,1.5*s);c.fill();c.fillStyle='#ffffff40';c.fillRect(-7*s,-20*s,3*s,17*s);c.fillStyle='#fdf7ea';c.fillRect(-6*s,-14*s,12*s,6*s);c.fillStyle='#52716b';c.fillRect(-4*s,-25*s,8*s,5*s);line(c,[[-3*s,-18*s],[-3*s,-8*s]],'#ffffffaa',2*s);c.fillStyle='#fff6b6';c.font='bold '+Math.max(12,18*s)+'px system-ui';c.textAlign='center';c.fillText('✦',0,-33*s);c.restore()}
function assignHidingPlaces(){const shelters=[...cover.filter(o=>o.type==='log'||o.type==='bush'),...castleCovers];animals.filter(a=>!a.mama).forEach((a,i)=>{const choices=a.type==='bunny'?shelters.filter(o=>o.bunnyShelter):shelters.filter(o=>!o.bunnyShelter),shelter=a.type==='parrot'?{...a.perch,type:'tree',size:1}:a.type==='spider'?(()=>{const rocks=cover.filter(o=>o.type==='rock'&&o.size>=.9);return rocks[Math.floor(Math.random()*rocks.length)]||cover.find(o=>o.type==='rock')})():a.type!=='bunny'&&Math.random()<.22?porchShelters[Math.floor(Math.random()*porchShelters.length)]:choices[Math.floor(Math.random()*choices.length)];a.shelter=shelter;a.hidden=true;a.radarRevealed=false;a.revealTimer=0;a.x=shelter.x;a.y=shelter.z;a.height=shelter.floorHeight||0;if(a.type==='parrot'){const branch=a.perchBranch;a.hidden=false;a.flightOffset=9;a.flightState='perched';a.flightRemaining=12;a.perched=true;a.flying=false;a.x=a.perch.x+branch.dx*.82;a.y=a.perch.z+branch.dz*.82;a.height=branch.baseHeight+(branch.tipHeight-branch.baseHeight)*.82;a.originX=a.perch.x+110;a.originY=a.perch.z+50}if(a.baby){a.baby.hidden=true;a.baby.x=a.x;a.baby.y=a.y}})}
function revealAnimals(dt){for(const a of animals.filter(a=>a.hidden&&!a.mama)){if(heroes[chosen].dog&&!a.hidden)a.bronxieSeen=true;if(!a.revealTimer&&!(a.hideCooldown>0)&&Math.hypot(player.x-a.x,player.y-a.y)<165&&Math.abs(jumpHeight-(a.height||0))<35){a.revealTimer=.7;hint.textContent='Something is rustling nearby…'}if(a.revealTimer){a.revealTimer-=dt;if(a.revealTimer<=0){const o=a.shelter,angle=o.type==='porch'?Math.PI/2:o.type==='log'?(player.x>=o.x?0:Math.PI):Math.atan2(player.y-o.z,player.x-o.x),distance=(o.type==='porch'?46:o.type==='log'?49:o.type==='bush'?40:o.type==='tree'?18:30*Math.max(o.rockWidth||1,o.rockDepth||1))*o.size+animalRadius(a)+8;a.x=o.x+Math.cos(angle)*distance;a.y=o.z+Math.sin(angle)*distance;a.hidden=false;a.radarRevealed=true;if(heroes[chosen].dog){a.bronxieSeen=true;if(a.baby)a.baby.bronxieSeen=true}a.height=o.floorHeight||0;a.foundShelter=o.type;a.revealTimer=0;if(a.type==='bunny')a.hideCooldown=5;moveSolid(a,a.x,a.y,animalRadius(a));a.originX=a.x;a.originY=a.y;a.heading=angle;if(a.type==='parrot'){a.flightOffset=9-(t%26);a.originX=a.x;a.originY=a.y}if(a.baby){a.baby.hidden=false;a.baby.radarRevealed=true;a.baby.x=a.x;a.baby.y=a.y}hint.textContent=a.name+' came out of hiding!'}}}}
function resetBonusBunny(a){const shelters=cover.filter(o=>o.bunnyShelter),shelter=shelters[Math.floor(Math.random()*shelters.length)];a.status='wild';a.catchRewardClaimed=false;a.catchPoints=0;a.sleeping=false;a.carried=false;a.height=0;a.hidden=true;a.radarRevealed=false;a.foundShelter=null;a.shelter=shelter;a.x=shelter.x;a.y=shelter.z;a.originX=a.x;a.originY=a.y;a.bunnyMeadow=true;a.revealTimer=0;a.hideCooldown=3;a.bunnyColor=Math.random()<.08?'pink':Math.random()<.5?'blue':'white';a.isPair=Math.random()<.1;a.value=(a.bunnyColor==='pink'?100:a.bunnyColor==='blue'?50:10)+(a.isPair?50:0);a.name=(a.bunnyColor==='pink'?'Rare pink':a.bunnyColor==='blue'?'Blue':'White')+(a.isPair?' bunny pair':' bunny')}
