function refreshFood(){document.getElementById('pellet-count').textContent='Fish food: '+pelletCount+' · Q'}function dropPellet(){if(state!=='playing')return;if(pelletCount<=0){hint.textContent='Find a fish-food bag first! Each bag holds 3 pellets.';return}pelletCount--;const pellet={x:player.x-Math.cos(yaw)*18,y:player.y-Math.sin(yaw)*18,height:castleCameraBase(),life:6};droppedPellets.push(pellet);refreshFood();hint.textContent='Pellets dropped! Eiza will race to eat them.'}function updateFood(dt){foodSpawnTimer-=dt;if(foodSpawnTimer<=0){foodSpawnTimer=12+Math.random()*6;if(foodBags.length<2)for(let attempt=0;attempt<12;attempt++){const angle=yaw+(Math.random()-.5)*Math.PI,distance=80+Math.random()*200,x=Math.max(45,Math.min(WORLD_W-45,player.x+Math.cos(angle)*distance)),y=Math.max(85,Math.min(WORLD_H-45,player.y+Math.sin(angle)*distance));if(!solidShapes.some(shape=>closestSolid(shape,x,y,15))){foodBags.push({x,y,life:10});break}}}for(const bag of foodBags){bag.life-=dt;if(Math.hypot(bag.x-player.x,bag.y-player.y)<28&&jumpHeight<18){bag.life=0;pelletCount+=3;refreshFood();hint.textContent='3 fish-food pellets! Press Q to distract Eiza.'}}foodBags=foodBags.filter(b=>b.life>0);for(const pellet of droppedPellets)pellet.life-=dt;droppedPellets=droppedPellets.filter(p=>p.life>0)}function foodArt(item,dropped=false){const q=project(item.x,item.y,item.height||0);if(!q||q.depth>1500)return;const s=q.scale;c.save();c.translate(q.x,q.y);if(dropped){for(let i=0;i<3;i++)ellipse(c,[-4,4,0][i]*s,[-2,-2,-8][i]*s,2.8*s,2*s,'#926a3d')}else{c.fillStyle='#dbbb84';c.beginPath();c.moveTo(-10*s,0);c.lineTo(-9*s,-22*s);c.lineTo(9*s,-22*s);c.lineTo(11*s,0);c.closePath();c.fill();line(c,[[-9*s,-20*s],[9*s,-20*s]],'#947348',2*s);c.fillStyle='#c1e0e6';c.fillRect(-7*s,-16*s,14*s,10*s);c.fillStyle='#547c87';c.font=Math.max(8,8*s)+'px system-ui';c.textAlign='center';c.fillText('FOOD',0,-9*s);for(let i=0;i<3;i++)ellipse(c,(i-1)*4*s,-3*s,1.5*s,1*s,'#775632')}c.restore()}
