const ponds=[{x:1480,z:820,rx:245,rz:155},{x:2630,z:1630,rx:285,rz:180},{x:3650,z:530,rx:180,rz:125}];function riverCenter(z){return 3350+Math.sin(z*.0024)*220+Math.sin(z*.0061)*48}function inWater(x,z){if(ponds.some(p=>((x-p.x)/p.rx)**2+((z-p.z)/p.rz)**2<1))return true;return Math.abs(x-riverCenter(z))<86}const shorelineReeds=[];ponds.forEach((pond,index)=>{for(let i=0;i<88;i++){const angle=i*Math.PI*2/88,seed=index*911+i*37,r=Math.sin(seed*12.9898)*43758.5453,noise=r-Math.floor(r);if(noise<.34)continue;const radius=1.045+noise*.12,x=pond.x+Math.cos(angle)*pond.rx*radius,z=pond.z+Math.sin(angle)*pond.rz*radius;if(inWater(x,z))continue;const q=Math.sin(seed*78.233)*43758.5453,height=22+(q-Math.floor(q))*74;shorelineReeds.push({x,z,height,seed,feather:height>69})}});for(let z=140;z<WORLD_H-100;z+=82){const wave=Math.sin(z*2.19)*43758.5453,n=wave-Math.floor(wave);if(n<.3)continue;for(const side of [-1,1])for(let j=0;j<2;j++){const rz=z+j*18+Math.sin(z+j*7)*6,spread=97+j*16+n*16,x=riverCenter(rz)+side*spread,q=Math.sin(z*1.71+j*13)*43758.5453,height=26+(q-Math.floor(q))*72;shorelineReeds.push({x,z:rz,height,seed:z+j*19+side*31,feather:height>69})}}function waterSpeedFactor(x,z,height=0){return height>28||!inWater(x,z)?1:.56}function drawWater(){const night=nightMode;for(const pond of ponds){const points=Array.from({length:32},(_,i)=>{const a=i*Math.PI*2/32;return[pond.x+Math.cos(a)*pond.rx,pond.z+Math.sin(a)*pond.rz]});groundPoly(points,night?'#205d70':'#397c88');groundPoly(points.map(([x,z])=>[pond.x+(x-pond.x)*.91,pond.z+(z-pond.z)*.91]),night?'#337f8a':'#55aab0');groundPoly(points.map(([x,z])=>[pond.x+(x-pond.x)*.68,pond.z+(z-pond.z)*.68]),night?'#479ca0':'#79c5c4');for(let i=0;i<4;i++){const x=pond.x-pond.rx*.45+i*pond.rx*.25,z=pond.z+Math.sin(i*2.1)*pond.rz*.27,shine=[[x-24,z],[x+24,z+4],[x+35,z+10],[x-8,z+7]];groundPoly(shine,night?'#c2eeee77':'#effff099')}}for(let z=55;z<WORLD_H-55;z+=90){const next=Math.min(WORLD_H-55,z+90),x1=riverCenter(z),x2=riverCenter(next),w=118;groundPoly([[x1-w,z],[x2-w,next],[x2+w,next],[x1+w,z]],night?'#205d70':'#397c88');const n=w*.82;groundPoly([[x1-n,z],[x2-n,next],[x2+n,next],[x1+n,z]],night?'#337f8a':'#55aab0');const inner=w*.48;groundPoly([[x1-inner,z],[x2-inner,next],[x2+inner,next],[x1+inner,z]],night?'#479ca0':'#79c5c4')}}const fenceSegments=[];for(let x=35;x<WORLD_W-35;x+=110){fenceSegments.push([x,44,Math.min(x+110,WORLD_W-35),44],[x,WORLD_H-44,Math.min(x+110,WORLD_W-35),WORLD_H-44])}for(let z=44;z<WORLD_H-44;z+=110){fenceSegments.push([35,z,35,Math.min(z+110,WORLD_H-44)],[WORLD_W-35,z,WORLD_W-35,Math.min(z+110,WORLD_H-44)])}function borderFenceArt(seg){const [x1,z1,x2,z2]=seg,p=project(x1,z1),q=project(x2,z2),a=project(x1,z1,34),b=project(x2,z2,34);if(!p||!q||!a||!b||Math.min(p.depth,q.depth)>1750)return;c.save();c.lineCap='round';c.strokeStyle='#72543c';c.lineWidth=Math.max(1.2,3*p.scale);c.beginPath();c.moveTo(p.x,p.y);c.lineTo(a.x,a.y);c.moveTo(q.x,q.y);c.lineTo(b.x,b.y);c.stroke();c.strokeStyle='#9b7751';c.lineWidth=Math.max(1,2*p.scale);for(const h of [12,25,34]){const l=project(x1,z1,h),r=project(x2,z2,h);if(!l||!r)continue;c.beginPath();c.moveTo(l.x,l.y);c.lineTo(r.x,r.y);c.stroke()}c.restore()}
