function paintBlossomFoliage(ctx,x,y,rx,ry,seed,density){ctx.save();ctx.translate(x,y);const colors=['#ce87a4','#e9a6bd','#efb6ca','#f6c8d8','#ffe0e9'];ctx.fillStyle='#e4a0b9';ctx.beginPath();for(let i=0;i<52;i++){const angle=i*Math.PI*2/52,edge=.89+.08*Math.sin(i*4.7+seed)+.05*Math.cos(i*2.3),xx=Math.cos(angle)*rx*edge,yy=Math.sin(angle)*ry*edge;i?ctx.lineTo(xx,yy):ctx.moveTo(xx,yy)}ctx.closePath();ctx.fill();for(let j=0;j<density;j++){const angle=j*2.399+seed,r=Math.sqrt((j+.5)/density),xx=Math.cos(angle)*rx*r*.95,yy=Math.sin(angle)*ry*r*.95,leaf=Math.max(1.2,rx*(.035+j%3*.01));ctx.save();ctx.translate(xx,yy);ctx.rotate(j*1.7);ctx.fillStyle=colors[(j+Math.floor(seed))%colors.length];ctx.beginPath();ctx.moveTo(-leaf,0);ctx.quadraticCurveTo(-leaf*.3,-leaf*.75,leaf,0);ctx.quadraticCurveTo(leaf*.25,leaf*.6,-leaf,0);ctx.fill();if(j%7===0){ctx.fillStyle='#ffe7ed';for(let k=0;k<5;k++){const a=k*Math.PI*2/5;ctx.beginPath();ctx.moveTo(0,0);ctx.quadraticCurveTo(Math.cos(a-.4)*leaf,Math.sin(a-.4)*leaf,Math.cos(a)*leaf*1.2,Math.sin(a)*leaf*1.2);ctx.quadraticCurveTo(Math.cos(a+.4)*leaf,Math.sin(a+.4)*leaf,0,0);ctx.fill()}}ctx.restore()}ctx.restore()}
function treeArt(tree){const root=project(tree.x,tree.z),top=project(tree.x,tree.z,tree.height);if(!root||!top||root.depth>1500||root.x<-300||root.x>W+300)return;if(tree.evergreen){evergreenArt(tree,root);return}const s=root.scale*(.85+tree.seed%3*.12);ellipse(c,root.x,root.y,25*s,6*s,'#698b5940');verticalTrunk(tree);for(const branch of treeBranches(tree)){const base=project(tree.x,tree.z,branch.baseHeight),tip=project(tree.x+branch.dx,tree.z+branch.dz,branch.tipHeight);if(base&&tip){line(c,[[base.x,base.y],[tip.x,tip.y]],'#806054',Math.max(2,5.5*s));line(c,[[base.x,base.y-1.5*s],[tip.x,tip.y-1.5*s]],'#b18a76',1.4*s);const fork=project(tree.x+branch.dx*.7,tree.z+branch.dz*.7,branch.tipHeight+15);if(fork){line(c,[[tip.x,tip.y],[fork.x,fork.y]],'#8b685d',2.3*s);for(let j=0;j<2;j++){const u=.3+j*.36,bloom=project(tree.x+branch.dx*u,tree.z+branch.dz*u,branch.baseHeight+(branch.tipHeight-branch.baseHeight)*u+12);if(bloom){blossomFoliage(bloom.x,bloom.y-4*s,20*s,13*s,tree.seed+j,22)}}}}}blossomFoliage(top.x,top.y,100*s,66*s,tree.seed,125)}
